// TH18 v1.00a st04mbs::MBoss -> MBoss1 (M:4-197), middle-boss non-spell.
// Source timerReset at M:11; M:23-25 movePos(0,128) + 100-frame stay; MBoss1 starts at source t=100.
// Card t0 is phase_begin; pattern waits 120 shell frames, then restores source t0.
const TIME_LIMIT: int = 2222;
const SOURCE_LIMIT: int = 2100;
const OPENING_BUFFER: int = 120;

const TH18_BIG_BALL2: int = 656; // source type19, radius 8.5, color3
const TH18_RING_BALL2: int = 464; // source type7, radius 4, color4

// Source M:72-74: ANIM a1 (4*initial speed retreat kept by sh_dist), SPEEDUP type1,
// WAIT100, VELTIME120 to the rank target. SPEEDUP adds 5-5*t/16 for t=0..16;
// set_accel -5/16 for 16 ticks plus the final base-speed frame reproduces the
// same 42.5px impulse and leaves the logical speed at 0.5.
xformdef MB_MOTION(target: fx) {
    set_speed(5.5fx);
    set_accel(-0.3125fx);
    wait(16);
    set_accel(0fx);
    set_speed(0.5fx);
    wait(101); // source WAIT100 plus the zero-boost frame
    set_accel((target-0.5fx)/120fx);
    wait(120);
    set_accel(0fx);
}

// Source MBoss1_at M:63-143.  et0: type19/color3, mode3, 1x1, speed0.5.
async sub at_big(rank: int) {
    var target: fx = 5fx;
    if rank == 0 { target = 3fx; }
    var interval: int = 5;
    if rank == 0 { interval = 20; }
    var count: int = 64;
    if rank == 0 { count = 16; }
    var g0: fx = 4fx;
    var g1: fx = 7fx;
    if rank == 0 { g0 = 12fx; g1 = 20fx; }
    if rank == 2 { g0 = 3fx; g1 = 6fx; }
    if rank == 3 { g0 = 3fx; g1 = 5fx; }

    sh_reset(0);
    sh_sprite(0, TH18_BIG_BALL2, 3);
    sh_ring(0, 1); // etAim mode3 fixed-direction ring
    sh_aim(0, 0);
    sh_count(0, 1, 1);
    sh_angle(0, -90deg, 10deg);
    sh_speed(0, 0.5fx, 0fx);
    sh_dist(0, -2fx); // ANIM a1: -4*0.5px
    sh_xform(0, MB_MOTION(target));

    // Source M:85-105: 64 (E16) shots, random 64px radial offset and 67.5+-20deg.
    for i in 0..count {
        var ra: angle = rand(65536) as angle; // RANDRAD
        sh_offset_rad(0, ra, 64fx);
        var u: fx = (rand(65536)-32768) as fx / 32768; // RANDF2
        var off: int = (3641fx*u) as int; // 20deg in BAM
        sh_angle(0, 12288bam+(off as angle), 10deg);
        sh_fire(0);
        wait(interval);
    }

    // Source M:106-141: F0 20->90deg and G (rank 12->20 / 4->7 / 3->6 / 3->5)
    // over 1800 frames; second loop, random angle on E%4==0 else player aim.
    var ft_start: int = $frame;
    var e: int = -1;
    loop {
        e = e+1;
        var elapsed: int = $frame-ft_start;
        if elapsed > 1800 { elapsed = 1800; }
        var f0: fx = 3641fx+(16384fx-3641fx)*(elapsed as fx)/1800fx;
        var g: fx = g0+(g1-g0)*(elapsed as fx)/1800fx;
        var ra2: angle = rand(65536) as angle;
        sh_offset_rad(0, ra2, 64fx);
        if e%4 == 0 {
            sh_angle(0, rand(65536) as angle, 10deg);
        } else {
            var u2: fx = (rand(65536)-32768) as fx / 32768;
            sh_angle(0, aim_player()+(((f0*u2) as int) as angle), 10deg);
        }
        sh_fire(0);
        wait(g as int);
    }
}

// Source MBoss1_at2 M:145-196, only H/L normal path.  type7/color4, mode3,
// 32/32/30/50 rays, speed0.5, same EX chain; 100-frame first wait then rank interval.
async sub at_small(rank: int) {
    var target: fx = 2.5fx;
    var n: int = 50;
    var interval: int = 50;
    if rank == 0 { target = 3fx; n = 32; interval = 100; }
    if rank == 1 { target = 5fx; n = 32; interval = 100; }
    if rank == 2 { target = 2fx; n = 30; interval = 100; }

    sh_reset(0);
    sh_sprite(0, TH18_RING_BALL2, 4);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_angle(0, -90deg, 10deg);
    sh_speed(0, 0.5fx, 0fx);
    sh_dist(0, -2fx);
    sh_xform(0, MB_MOTION(target));

    wait(100);
    loop {
        sh_fire(0);
        wait(interval);
    }
}

// Source MBoss1 M:35-61.  MBoss1_at is all ranks; MBoss1_at2 is !HL.
async sub pattern() {
    wait(OPENING_BUFFER);
    move_to(0, 0fx, 128fx, EASE_LINEAR); // source movePos(0,128)
    wait(100); // source M:25 wait(100)
    var rank: int = global(GVAR_RANK);
    spawn at_big(rank);
    if rank >= 2 { spawn at_small(rank); }

    // Source M:45-59: six absolute movePosTime(160, mode9) legs, cycling.
    loop {
        move_to(160, 192fx, 32fx, EASE_QUAD_IN_OUT);
        wait(160);
        move_to(160, -192fx, 96fx, EASE_QUAD_IN_OUT);
        wait(160);
        move_to(160, 192fx, 144fx, EASE_QUAD_IN_OUT);
        wait(160);
        move_to(160, -192fx, 224fx, EASE_QUAD_IN_OUT);
        wait(160);
        move_to(160, 192fx, 224fx, EASE_QUAD_IN_OUT);
        wait(160);
        move_to(160, -192fx, 320fx, EASE_QUAD_IN_OUT);
        wait(160);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(20fx); // source setHitbox(40,40) -> ordinary circle width/2
    set_hurtbox(24fx); // source setHurtbox(48,48)
    move_to(0, 0fx, 128fx, EASE_LINEAR); // source M:23
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

// Source S:1210 control enemy spawns MBoss at (-192,-32); the extra controller
// stays at (0,0) with body collision off, the real boss keeps source judgement.
async sub controller() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    _ = spawn_enemy(-192fx, -32fx, 20000, 0, 0, 0, boss_main);
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1, 0, 0, 0, controller);
    loop { wait(600); }
}
